mutation createTrunk($trunk: TrunkCreate!) {
  trunk { createTrunk(trunk: $trunk) { trunkId } }
}

input TrunkCreate {
  name: String!               nom unique dans l'organisation
  organizationId: UUID!       le client
  siteAddressId: UUID!        adresse du site principal
  hostingEnvironmentId: UUID  cluster (sinon cluster par défaut)
  planId: UUID                forfait — null = pay-as-you-go
  channels: Int               total d'appels simultanés du trunk
  pai: String!                numéro présenté (+33123456789)
  gatewayIds: [UUID]          passerelles SIP (optionnel)
  teamsPBX: Boolean!          true = Microsoft Teams, false = standard classique
  sites: [TrunkSiteCreate]!   au moins 1 site
}

input TrunkSiteCreate {
  siteId: UUID!
  channels: Int!              canaux de CE site (≥ 1)
  numbersId: [UUID]!          au moins 1 numéro
}

Réponse : { trunkId } seulement → ensuite getTrunk(trunkId) pour les détails.
